question.answer:
threshold = 5

def summarise(readings):
    count = 0
    total = 0
    for reading in readings:
        count = count + 1
        total = total + reading
    return count, total

def clear_log():
    print("log cleared")

def over_threshold(reading):
    return reading > threshold

def tighten():
    threshold = 1
    return threshold

