question.answer:
def collatz_steps(n):
    if n <= 1:
        return 0
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps = steps + 1
    return steps

def log_start():
    print("logger armed")
